from pathlib import Path
import json
out=Path('public/campaigns/visitorping-launch')
base='https://visitorping.com/for-founders'
ads=[{'id':'notification','headline':'Your website gets a visitor. Your iPhone pings.','body':'Just launched your website? See visitor activity in a live dashboard and receive notifications on your iPhone. Meet VisitorPing.','utm_content':'notification_a'},{'id':'refreshing','headline':'Still refreshing your analytics?','body':'Keep building. VisitorPing brings website visitor notifications to your iPhone, with a live dashboard when you want to look closer.','utm_content':'refreshing_b'}]
from urllib.parse import urlencode
for a in ads:a['url']=base+'?'+urlencode({'utm_source':'reddit','utm_medium':'paid_social','utm_campaign':'founder_first_visitors_202609','utm_content':a['utm_content']})
(out/'campaign.json').write_text(json.dumps({'status':'draft_not_published','audience':'English-speaking solo SaaS founders with recently launched websites','channel':'Reddit','geography_proposed':['United States'],'currency':'USD','proposed_total_spend_cap':100,'budget_approved':False,'duration_days':7,'targeting':'Eligible SaaS, startup and side-project communities; confirm actual availability in Ads Manager','primary_signal':'First real visitor recorded after tracker installation','attribution_status':'UTM-tagged landing and signup links prepared; campaign-to-workspace activation attribution not yet verified','ads':ads},indent=2))
css='''*{box-sizing:border-box}body{margin:0;background:#080f10;color:#f6faf8;font-family:Arial,Helvetica,sans-serif}a{color:#34d399}main{max-width:1120px;margin:auto;padding:48px 28px}h1{font-size:clamp(38px,6vw,72px);line-height:1.02;letter-spacing:-.055em;max-width:900px;margin:24px 0}h2{font-size:30px;letter-spacing:-.03em;margin:0 0 20px}h3{font-size:20px}p,li{line-height:1.65;color:#b5c9c1}header{display:flex;justify-content:space-between;gap:20px;align-items:center;border-bottom:1px solid #263932;padding-bottom:22px}.brand{font-weight:800;color:white;font-size:21px;display:flex;align-items:center;gap:10px}.brand img{width:32px;height:32px;object-fit:contain}.green{color:#34d399}.muted{font-size:14px;color:#a3b7af}.section{padding:48px 0;border-bottom:1px solid #263932}.grid{display:grid;grid-template-columns:1fr 1fr;gap:28px}.asset{width:100%;border-radius:16px;border:1px solid #263932}video{width:100%;border-radius:16px;background:#000}.button{display:inline-block;text-decoration:none;background:#34d399;color:#051b13;padding:14px 20px;border-radius:9px;font-weight:700;margin:10px 12px 8px 0}.secondary{background:transparent;border:1px solid #567568;color:white}blockquote{margin:20px 0;padding:20px;border-left:3px solid #34d399;background:#11231c;line-height:1.6}.link{font-family:monospace;font-size:12px;overflow-wrap:anywhere}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}@media(max-width:700px){.grid,.steps{grid-template-columns:1fr}header{align-items:start}main{padding:28px 20px}}'''
head='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VisitorPing launch campaign</title><style>'+css+'</style><body><main>'
brand='<div class="brand"><img src="assets/logo.png" alt="">VisitorPing</div>'
cards=''.join('<article><h3>'+a['headline']+'</h3><p>'+a['body']+'</p><p class="link">'+a['url']+'</p></article>' for a in ads)
review=head+'<header>'+brand+'<span class="muted">Campaign review · Prepared September 10, 2026</span></header><h1>Your first visitors.<br><span class="green">Your first campaign.</span></h1><p>A founder-focused campaign built around one visible benefit: website activity arriving on your iPhone.</p><a class="button" href="landing.html">Preview landing page</a><a class="button secondary" href="campaign.json" download>Download campaign settings</a><section class="section"><h2>Ready-to-use creative</h2><div class="grid"><article><img class="asset" src="assets/ad-notification.png" alt="Your website gets a visitor. Your iPhone pings."><a class="button secondary" href="assets/ad-notification.png" download>Download ad A</a></article><article><img class="asset" src="assets/ad-refreshing.png" alt="Still refreshing your analytics?"><a class="button secondary" href="assets/ad-refreshing.png" download>Download ad B</a></article></div></section><section class="section"><h2>15-second product explainer</h2><video controls playsinline preload="metadata" poster="assets/video-poster.png"><source src="assets/visitorping-demo.mp4" type="video/mp4"></video><p class="muted">Silent, captioned explainer. Uses VisitorPing’s existing interactive-preview screenshot and a clearly labelled illustrative notification. This is not a recording of a real customer.</p><a class="button secondary" href="assets/visitorping-demo.mp4" download>Download MP4</a></section><section class="section"><h2>Ad copy and tracked destinations</h2><div class="grid">'+cards+'</div></section><section class="section"><h2>The launch settings</h2><div class="steps"><article><h3>One audience</h3><p>Solo founders with recently launched websites. Start with English-language US traffic and eligible founder communities.</p></article><article><h3>One bounded test</h3><p>Proposed: $100 total across seven days. Two creatives, one audience. Budget is not yet approved; no spend has started.</p></article><article><h3>One useful signal</h3><p>Look for newly connected websites recording their first real visitor. Signups, installs and payment remain supporting measures.</p></article></div></section><section class="section"><h2>Publication status</h2><p>Assets are prepared. The production landing route is implemented but not deployed. Google Ads OAuth returned invalid_grant; Reddit account access is not connected. No ads or posts have been published.</p><p>Campaign tags are included in the landing and signup URLs. Per-campaign activation attribution still needs verification before reporting acquisition costs.</p></section></main></body></html>'
(out/'index.html').write_text(review)
landing=head+'<header>'+brand+'<a href="https://visitorping.com/pricing">Plans and pricing</a></header><h1>Your website gets a visitor.<br><span class="green">Your iPhone pings.</span></h1><p>You put your website out into the world. Now see when someone arrives—with live visitor activity in your dashboard and notifications on your iPhone.</p><a data-destination="/signup" class="button" href="https://visitorping.com/signup">Start your 14-day trial</a><a class="button secondary" href="#demo">See it in action</a><section id="demo" class="section"><video controls playsinline poster="assets/video-poster.png"><source src="assets/visitorping-demo.mp4" type="video/mp4"></video><p class="muted">Illustrative product demonstration using example data.</p></section><section class="section"><h2>Stay close to your launch.</h2><div class="steps"><article><h3>Notice the arrival</h3><p>Receive visitor notifications on your iPhone when your configured alerts trigger.</p></article><article><h3>Follow the visit</h3><p>See live page activity and available traffic-source information in your dashboard.</p></article><article><h3>Use your own website</h3><p>Connect your SaaS site, WordPress page, Shopify store or another supported website.</p></article></div></section><section class="section"><h2>From your website to your pocket.</h2><ol><li>Create your VisitorPing account and add your website.</li><li>Install the tracking script using your platform’s guide.</li><li>Connect your iPhone and choose your notification preferences.</li></ol><p>Visitors are anonymous by default. A visit does not reveal a person’s name.</p><a data-destination="/signup" class="button" href="https://visitorping.com/signup">Start your 14-day trial</a><a data-destination="/pricing" class="button secondary" href="https://visitorping.com/pricing">See plans and pricing</a></section><p class="muted">Campaign preview. Production implementation reuses VisitorPing’s existing marketing layout and interactive demo.</p></main><script>const params=new URLSearchParams(location.search);document.querySelectorAll("[data-destination]").forEach(a=>{const u=new URL(a.dataset.destination,"https://visitorping.com");for(const k of ["utm_source","utm_medium","utm_campaign","utm_content","utm_term"]){const v=params.get(k);if(v&&v.length<=200)u.searchParams.set(k,v)}a.href=u.href});</script></body></html>'
(out/'landing.html').write_text(landing)
# Deterministic typography-only ad and motion composition. Product screenshot remains unmodified.
(out/'motion.html').write_text('''<!doctype html><html><meta charset="utf-8"><style>*{box-sizing:border-box}body{margin:0;background:#070f0d;color:#f5fbf8;font-family:Arial,sans-serif;width:1080px;height:1080px;overflow:hidden}.canvas{padding:70px;height:100%;position:relative}.brand{display:flex;align-items:center;gap:16px;font-size:32px;font-weight:800}.brand img{width:44px;height:44px;object-fit:contain}h1{font-size:90px;letter-spacing:-5px;line-height:1.03;max-width:920px;margin:65px 0 32px}em{font-style:normal;color:#34d399}.sub{font-size:31px;line-height:1.45;max-width:700px;color:#bdcec6}.notification{margin-top:55px;padding:32px;border:1px solid #416454;border-radius:24px;background:#14271e;max-width:750px}.notification strong{display:block;color:#34d399;font-size:25px;margin-bottom:16px}.notification p{font-size:32px;margin:0}.note{font-size:19px;color:#a6bcb0;margin-top:16px}.product{position:absolute;right:66px;bottom:90px;width:625px;max-height:610px;object-fit:contain}.footer{position:absolute;bottom:52px;left:70px;right:70px;display:flex;justify-content:space-between;font-size:25px}.cta{background:#34d399;color:#08170f;display:inline-block;padding:22px 32px;border-radius:12px;font-size:28px;font-weight:700;margin-top:40px}.hidden{display:none}</style><div class="canvas"><div class="brand"><img src="assets/logo.png">VisitorPing</div><h1 id="headline"></h1><div class="sub" id="sub"></div><div id="notice" class="notification"><strong>VisitorPing · now</strong><p>A visitor is on your website.</p><div class="note">Illustrative notification</div></div><img id="product" class="product hidden" src="assets/product-demo.png"><div id="cta" class="cta hidden">See how it works →</div><div class="footer"><span>visitorping.com</span><span id="label">Website activity. In your pocket.</span></div></div><script>window.frame=t=>{let phase=t<3?0:t<7?1:t<12?2:3;document.getElementById('headline').innerHTML=['Your website gets<br>a visitor.','Your iPhone<br><em>pings.</em>','Follow the visit.<br><em>Live.</em>','Keep building.<br><em>Stay in the loop.</em>'][phase];document.getElementById('sub').style.display=phase===2?'none':'block';document.getElementById('sub').textContent=['You put your website out into the world.','Notice website activity without keeping a dashboard open.','VisitorPing’s interactive preview.','Live visitor activity and iPhone notifications.'][phase];document.getElementById('notice').classList.toggle('hidden',phase!==1);document.getElementById('product').classList.toggle('hidden',phase!==2);document.getElementById('cta').classList.toggle('hidden',phase!==3);document.getElementById('label').textContent=phase===2?'Example data':'Website activity. In your pocket.'};window.frame(4);if(location.search.includes('variant=b')){document.getElementById('headline').innerHTML='Still refreshing<br><em>your analytics?</em>';document.getElementById('sub').textContent='Keep building. Let website visitor notifications come to your iPhone.';}</script></html>''')
